SELECT id, organization_id AS organizationId, site_id AS siteId,
       waypoint_code AS code, status, created_at AS createdAt,
       updated_at AS updatedAt, archived_at AS archivedAt, version
FROM mine_waypoint
WHERE organization_id = #{organizationId} AND site_id = #{siteId}

    AND waypoint_code ILIKE CONCAT('%', #{keyword}, '%')


    AND status = #{status}

ORDER BY waypoint_code, id
OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*)
FROM mine_waypoint
WHERE organization_id = #{organizationId} AND site_id = #{siteId}

    AND waypoint_code ILIKE CONCAT('%', #{keyword}, '%')


    AND status = #{status}

SELECT COUNT(*) FROM mine_waypoint_version waypoint_version JOIN mine_waypoint waypoint ON waypoint.id = waypoint_version.waypoint_id AND waypoint.organization_id = waypoint_version.organization_id AND waypoint.site_id = waypoint_version.site_id WHERE waypoint_version.organization_id = #{organizationId} AND waypoint_version.site_id = #{siteId} AND waypoint_version.coordinate_system_id = #{coordinateSystemId} AND waypoint_version.status = 'PUBLISHED' AND waypoint.status = 'ACTIVE' AND waypoint_version.valid_from <= #{validFrom}
AND (waypoint_version.valid_to IS NULL OR waypoint_version.valid_to >= #{validTo})
AND waypoint_version.valid_to IS NULL
AND waypoint_version.id IN
#{versionId}

